// Writes supabase/seed.local.sql (gitignored) so the seeded test accounts
// (@seed.skillshift.test) can sign in with DEMO_PASSWORD from .env.
//
//   dart run tool/gen_demo_seed.dart
//
// The password never enters git: it lives in .env and the generated file.
import 'dart:io';

void main() {
  final env = File('.env');
  if (!env.existsSync()) {
    stderr.writeln('No .env found. Copy .env.example to .env first.');
    exit(1);
  }

  String? password;
  for (final line in env.readAsLinesSync()) {
    final t = line.trim();
    if (t.startsWith('DEMO_PASSWORD=')) {
      password = t.substring('DEMO_PASSWORD='.length).trim();
      if (password.length >= 2 &&
          (password.startsWith('"') && password.endsWith('"') ||
              password.startsWith("'") && password.endsWith("'"))) {
        password = password.substring(1, password.length - 1);
      }
    }
  }

  if (password == null || password.length < 12) {
    stderr.writeln('Set DEMO_PASSWORD in .env (at least 12 characters).');
    exit(1);
  }

  final escaped = password.replaceAll("'", "''");
  final sql =
      '''
-- GENERATED by tool/gen_demo_seed.dart. Do not commit (gitignored).
-- Sets the demo password on seeded TEST accounts only.
update auth.users
set encrypted_password = extensions.crypt('$escaped', extensions.gen_salt('bf'))
where email like '%@seed.skillshift.test';
''';

  File('supabase/seed.local.sql').writeAsStringSync(sql);
  stdout.writeln(
    'Wrote supabase/seed.local.sql. '
    'Run `supabase db reset` (local) to apply it.',
  );
}
